document.documentElement.dataset.theme=theme;
const themeLabel=()=>language==='de'?(theme==='dark'?'Hellen Modus aktivieren':'Dunklen Modus aktivieren'):(theme==='dark'?'Switch to light mode':'Switch to dark mode');
function syncTheme(){document.documentElement.dataset.theme=theme;const b=document.querySelector('#theme-toggle');if(b){b.textContent=theme==='dark'?'☀':'☾';b.setAttribute('aria-label',themeLabel());b.title=themeLabel();b.setAttribute('aria-pressed',String(theme==='dark'))}}
const ui={en:{lang:'Language',edition:'GERMANY · POLITICAL PERSPECTIVES',about:'How it works',perspective:'Your perspective, one choice at a time',stand:'Where do you stand?',intro:'Consider both sides. Choose what feels right to you.',questions:'The 21 questions',statement:'Statement',for:'The case for',against:'The case against',agree:'Agree',disagree:'Disagree',dont:'Don’t care',back:'← Back',answered:'answered',results:'See my results',next:'Next question',finish:'Finish unanswered',note:'No right answers. “Don’t care” leaves a topic out of your match.',yourResults:'Your results',counted:'topics counted',common:'Your political common ground.',overall:'See the overall picture. Then follow the connections behind it.',alignment:'Your alignment',across:'Across the statements you care about.',follow:'Follow your answers',graphHint:'Hover, focus or tap a topic or party to trace its connections.',full:'Full',partial:'Partial',select:'Select a topic or party to explore where your answer aligns.',aligned:'Aligned:',noAlign:'No party clearly aligns on this statement.',review:'Review my answers',restart:'Start again',noPositions:'No positions to compare yet.',skipped:'You chose “Don’t care” for every topic, so there is no meaningful ranking. Give at least one statement an agree or disagree answer to see your connections.',yourAnswers:'YOUR ANSWERS',parties:'PARTIES',showParties:'Show aligned parties',showTopics:'Show topics aligned with your answers',alignedTopics:'Topics aligned with your answer',excluded:'Excluded from scoring. No alignment is implied.',methodTitle:'About the questions & scoring',programme:'programme ↗',independent:'Independent exploration. No affiliation with Wahl-O-Mat or any party.',privacy:'Your answers stay in this page. No account. No tracking.',cross:'Cross-party programme comparison ↗',m1:'This is an independent, illustrative comparison of seven parties, based mainly on their 2025 federal election programmes. These 21 statements and party scores are editorial interpretations, not answers authorised by the parties. They are not a validated replacement for an official election questionnaire. State programmes and subsequent policy changes can differ.',m2:'Agree and disagree count equally: a full match earns 1 point, an opposite answer 0, and a mixed party position 0.5. Qualified positions may earn 0.25 or 0.75. “Don’t care” is excluded entirely, not counted as neutrality. Unknown party positions are also excluded, and the number compared is shown. Percentages are rounded; ties are equal compatibility. The graph shows only parties whose position leans in the direction of your answer; dashed lines indicate partial alignment.',m3:'Some questions were narrowed to avoid combining different policies: pensions concerns invested funds, privacy concerns indiscriminate metadata retention, and social values concerns adults’ legal gender records. Union’s investment-borrowing position is marked mixed because its 2025 programme and subsequent borrowing decisions differ. BSW’s nuclear position is left unknown rather than inferred.'},de:{lang:'Sprache',edition:'DEUTSCHLAND · POLITISCHE PERSPEKTIVEN',about:'So funktioniert’s',perspective:'Deine Perspektive, These für These',stand:'Wo stehst du?',intro:'Betrachte beide Seiten. Wähle, was sich für dich richtig anfühlt.',questions:'Die 21 Thesen',statement:'These',for:'Dafür spricht',against:'Dagegen spricht',agree:'Zustimmung',disagree:'Ablehnung',dont:'Egal',back:'← Zurück',answered:'beantwortet',results:'Ergebnisse anzeigen',next:'Nächste These',finish:'Offene Fragen beenden',note:'Es gibt keine richtigen Antworten. „Egal“ wird nicht in deinen Vergleich einbezogen.',yourResults:'Deine Ergebnisse',counted:'Themen gewertet',common:'Dein politischer Common Ground.',overall:'Das Gesamtbild. Dann die Verbindungen dahinter.',alignment:'Deine Übereinstimmung',across:'Über die Themen, die dir wichtig sind.',follow:'Deine Antworten verfolgen',graphHint:'Bewege den Cursor, fokussiere oder tippe auf ein Thema oder eine Partei, um Verbindungen zu sehen.',full:'Vollständig',partial:'Teilweise',select:'Wähle ein Thema oder eine Partei, um passende Antworten zu erkunden.',aligned:'Passend:',noAlign:'Zu dieser These passt keine Partei eindeutig.',review:'Antworten prüfen',restart:'Neu starten',noPositions:'Noch keine Positionen zum Vergleichen.',skipped:'Du hast bei allen Themen „Egal“ gewählt. Gib mindestens eine These mit Zustimmung oder Ablehnung an, um Verbindungen zu sehen.',yourAnswers:'DEINE ANTWORTEN',parties:'PARTEIEN',showParties:'Passende Parteien anzeigen',showTopics:'Themen passend zu deinen Antworten anzeigen',alignedTopics:'Themen passend zu deiner Antwort',excluded:'Nicht gewertet. Daraus wird keine Übereinstimmung abgeleitet.',methodTitle:'Über die Thesen und die Auswertung',programme:'Wahlprogramm ↗',independent:'Unabhängige Orientierung. Keine Verbindung zu Wahl-O-Mat oder einer Partei.',privacy:'Deine Antworten bleiben auf dieser Seite. Kein Konto. Kein Tracking.',cross:'Parteienvergleich der Wahlprogramme ↗',m1:'Dies ist ein unabhängiger, beispielhafter Vergleich von sieben Parteien, der hauptsächlich auf ihren Bundestagswahlprogrammen 2025 beruht. Die 21 Thesen und Parteipositionen sind redaktionelle Einordnungen, keine von den Parteien autorisierten Antworten. Sie ersetzen keinen offiziellen Wahlfragebogen. Landesprogramme und spätere politische Änderungen können abweichen.',m2:'Zustimmung und Ablehnung zählen gleich: Eine vollständige Übereinstimmung ergibt 1 Punkt, eine entgegengesetzte Antwort 0 und eine gemischte Parteiposition 0,5. Abgestufte Positionen können 0,25 oder 0,75 ergeben. „Egal“ wird vollständig ausgeschlossen und nicht als Neutralität gezählt. Unklare Parteipositionen werden ebenfalls ausgeschlossen; die Zahl der verglichenen Themen wird angezeigt. Prozentwerte sind gerundet; Gleichstände bedeuten gleiche Kompatibilität. Die Grafik zeigt nur Parteien, deren Position in Richtung deiner Antwort geht; gestrichelte Linien zeigen eine teilweise Übereinstimmung.',m3:'Einige Thesen wurden bewusst eingegrenzt, damit unterschiedliche Politikbereiche nicht vermischt werden: Bei der Rente geht es um Investitionen, beim Datenschutz um die anlasslose Speicherung von Metadaten und bei gesellschaftlichen Fragen um den rechtlichen Geschlechtseintrag von Erwachsenen. Die Position der Union zu kreditfinanzierten Investitionen ist als gemischt markiert, weil sich Wahlprogramm und spätere Kreditentscheidungen unterscheiden. Die Atomposition des BSW bleibt mangels eindeutiger Grundlage offen.'}};
const t=k=>ui[language][k]||ui.en[k]||k,q=(x,k)=>language==='de'?(x.de?.[k]||x[k]):x[k],lab=a=>a===1?t('agree'):a===-1?t('disagree'):a===0?t('dont'):(language==='de'?'Nicht beantwortet':'Unanswered'),count=()=>answers.filter(a=>a!==null).length;
function brand(){return`<header><div class="brand"><span class="logo" aria-hidden="true">✓</span>common ground<span class="edition">/ ${questions.length}</span></div><span class="edition country">${t('edition')}</span><div class="header-actions"><button class="theme-toggle" id="theme-toggle" aria-label="${themeLabel()}" title="${themeLabel()}" aria-pressed="${theme==='dark'}">${theme==='dark'?'☀':'☾'}</button><div class="language-toggle" role="group" aria-label="${t('lang')}"><button id="lang-en" class="${language==='en'?'active':''}">EN</button><button id="lang-de" class="${language==='de'?'active':''}">DE</button></div><button class="text-button" id="about">${t('about')}</button></div></header>`}function method(){return`<details class="method" id="method"><summary>${t('methodTitle')}</summary><p>${t('m1')}</p><p>${t('m2')}</p><p>${t('m3')}</p><p>${language==='de'?'Die neuen Thesen 19–21 beziehen sich auf Wahlprogramme von 2025. Unklare Positionen werden ausgeschlossen. Bei These 19 zählt das damalige SPD-Programm, nicht die spätere Koalitionspolitik. Bei These 21 bleiben SPD und BSW mangels eindeutiger Belege offen.':'New statements 19–21 use 2025 election programmes. Unclear positions are excluded. Statement 19 uses the SPD’s election programme, not its later coalition policy. For statement 21, SPD and BSW remain unscored because evidence is unclear.'}</p><div>${questions.filter(x=>x.evidence).map(x=>`<a href="${x.evidence}" target="_blank" rel="noopener noreferrer">${x.id}. ${q(x,'topic')} ↗</a>`).join('')}</div><div>${sources.map(([n,u])=>`<a href="${u}" target="_blank" rel="noopener noreferrer">${n} ${t('programme')}</a>`).join('')}</div><p><a href="https://www.tagesschau.de/inland/bundestagswahl/programmvergleich" target="_blank" rel="noopener noreferrer">${t('cross')}</a></p></details>`}function footer(){return`<footer><span>${t('privacy')}</span><span class="author-credit">Joey Prüssing</span></footer>`}
function render(){document.documentElement.lang=language;root.innerHTML=brand()+`<main class="shell">${view==='quiz'?quiz():results()}</main>`+footer();document.querySelector('#theme-toggle').onclick=()=>{theme=theme==='dark'?'light':'dark';try{localStorage.setItem('common-ground-theme',theme)}catch{}syncTheme()};document.querySelector('#about').onclick=()=>{const m=document.querySelector('#method');m.open=true;m.scrollIntoView({behavior:'smooth',block:'center'})};document.querySelector('#lang-en').onclick=()=>{language='en';render()};document.querySelector('#lang-de').onclick=()=>{language='de';render()};view==='quiz'?bindQuiz():bindResults()}
function quiz(){const x=questions[index];return`<div class="intro"><div><div class="eyebrow">${t('perspective')}</div><h1>${t('stand')}</h1><p class="muted">${t('intro')}</p></div><div class="step-label"><strong>${String(index+1).padStart(2,'0')}</strong> <span class="muted">/ ${questions.length}</span></div></div><div class="quiz-layout"><aside class="sidebar"><h3>${t('questions')}</h3><nav class="topics" aria-label="${t('questions')}">${questions.map((x,i)=>`<button class="topic ${i===index?'active':''} ${answers[i]!==null?'done':''}" data-index="${i}" aria-label="${i+1}: ${q(x,'topic')}, ${lab(answers[i])}"><span class="n">${answers[i]!==null&&i!==index?'✓':String(i+1).padStart(2,'0')}</span><span class="topic-name">${q(x,'topic')}</span></button>`).join('')}</nav></aside><div><section class="card"><div class="progress"><div style="width:${count()/questions.length*100}%"></div></div><div class="question"><div class="question-top"><span class="eyebrow">${t('statement')} ${String(x.id).padStart(2,'0')}</span><span class="tag">${q(x,'category')}</span></div><h2 id="question-title" tabindex="-1">${q(x,'statement')}</h2><div class="argument-grid"><div class="argument"><h3><span class="sign">+</span>${t('for')}</h3><p>${q(x,'pro')}</p></div><div class="argument con"><h3><span class="sign">−</span>${t('against')}</h3><p>${q(x,'con')}</p></div></div><div class="answers">${[[1,'✓',t('agree')],[-1,'×',t('disagree')],[0,'—',t('dont')]].map(([v,s,l])=>`<button class="answer ${answers[index]===v?'selected':''}" data-answer="${v}" aria-pressed="${answers[index]===v}"><span>${s}</span>${l}</button>`).join('')}</div><div class="navrow"><button class="text-button" id="back" ${index===0?'disabled':''}>${t('back')}</button><span class="hint">${count()} / ${questions.length} ${t('answered')}</span><button class="primary" id="next" ${answers[index]===null?'disabled':''}>${count()===questions.length?t('results'):index===questions.length-1?t('finish'):t('next')} →</button></div></div></section></div></div>${method()}`}
function bindQuiz(){document.querySelectorAll('[data-index]').forEach(b=>b.onclick=()=>{index=+b.dataset.index;render()});document.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>{answers[index]=+b.dataset.answer;if(count()===questions.length)view='results';else index=index===questions.length-1?answers.indexOf(null):index+1;render()});document.querySelector('#back').onclick=()=>{index--;render()};document.querySelector('#next').onclick=()=>{if(answers[index]===null)return;if(count()===questions.length)view='results';else index=index===questions.length-1?answers.indexOf(null):index+1;render()}}
function results(){const ranked=rank(answers),answered=answers.filter(a=>a!==0&&a!==null).length;return`<div class="result-head"><div class="kicker"><span class="eyebrow">${t('yourResults')}</span><span class="pill">${answered} ${t('counted')}</span></div><h1>${t('common')}</h1><p class="muted">${t('overall')}</p></div>${answered?`<div class="results-grid"><section class="card rankings"><h2>${t('alignment')}</h2><p class="muted">${t('across')}</p>${ranked.map(r=>{const p=parties[r.party];return`<div class="rank-item" style="--party:${p[2]}"><div class="rank-line"><span class="swatch"></span><strong>${p[0]}</strong><span class="percent">${r.score===null?'—':r.score+'%'}</span></div><div class="bar"><span style="width:${r.score??0}%"></span></div><span class="coverage">${r.count} ${t('counted')}</span></div>`}).join('')}</section><section class="card graph-card"><div class="graph-top"><div><h2>${t('follow')}</h2><p class="muted">${t('graphHint')}</p></div><div class="graph-legend">── ${t('full')} &nbsp; ╌ ${t('partial')}</div></div><div class="graph-wrap"><svg class="network" viewBox="0 0 640 680"></svg></div><div class="graph-detail" aria-live="polite">${t('select')}</div></section></div>`:`<section class="card all-skipped"><h2>${t('noPositions')}</h2><p class="muted">${t('skipped')}</p></section>`}<div class="result-actions"><button class="primary" id="review">${t('review')}</button><button class="text-button" id="restart">${t('restart')}</button></div>${method()}`}function bindResults(){document.querySelector('#review').onclick=()=>{view='quiz';index=0;render()};document.querySelector('#restart').onclick=()=>{answers=Array(questions.length).fill(null);view='quiz';index=0;render()};document.querySelector('.network')&&drawGraph()}
async function drawGraph(){d3??=await import('./vendor/d3-shape.js');const svg=document.querySelector('.network'),link=d3.linkHorizontal(),edges=[];questions.forEach((x,i)=>parties.forEach((p,j)=>{if(answers[i]&&x.positions[j]!==null&&answers[i]*x.positions[j]>0)edges.push({i,j,partial:Math.abs(x.positions[j])<1})}));svg.innerHTML=`<text x="12" y="26" fill="#829087" font-size="11" letter-spacing="1.5">${t('yourAnswers')}</text><text x="497" y="26" fill="#829087" font-size="11" letter-spacing="1.5">${t('parties')}</text><g>${edges.map(e=>`<path class="edge" data-q="${e.i}" data-p="${e.j}" ${e.partial?'stroke-dasharray="5 4"':''} d="${link({source:[215,58+e.i*34],target:[485,90+e.j*85]})}"/>`).join('')}</g>${questions.map((x,i)=>`<g class="node" tabindex="0" role="button" data-node="${i}" transform="translate(0 ${58+i*34})"><text x="12" y="5">${String(i+1).padStart(2,'0')} &nbsp; ${q(x,'topic')}</text><circle cx="215" r="5"/></g>`).join('')}${parties.map((p,j)=>`<g class="party-node" tabindex="0" role="button" data-party="${j}" transform="translate(485 ${90+j*85})"><circle r="6" fill="${p[2]}"/><text x="16" y="5" fill="${p[2]}">${p[0]}</text></g>`).join('')}`;svg.querySelectorAll('[data-node]').forEach(n=>{const i=+n.dataset.node;n.onmouseenter=()=>highlight(i);n.onmouseleave=()=>highlight(pinned);n.onclick=()=>{pinned=pinned===i?null:i;pinnedParty=null;highlight(pinned)}});svg.querySelectorAll('[data-party]').forEach(n=>{const j=+n.dataset.party;n.onmouseenter=()=>party(j);n.onmouseleave=()=>pinnedParty===null?highlight(pinned):party(pinnedParty);n.onclick=()=>{pinnedParty=pinnedParty===j?null:j;pinned=null;pinnedParty===null?highlight(null):party(pinnedParty)}});highlight(pinned)}
function highlight(i){document.querySelectorAll('.edge').forEach(e=>{const on=+e.dataset.q===i;e.classList.toggle('lit',on);e.style.stroke=on?parties[+e.dataset.p][2]:'';e.style.opacity=i===null?'':on?.9:.07});document.querySelectorAll('[data-node]').forEach(n=>n.classList.toggle('active',+n.dataset.node===i));document.querySelectorAll('[data-party]').forEach(n=>n.classList.toggle('active',i!==null&&[...document.querySelectorAll(`.edge[data-q="${i}"]`)].some(e=>+e.dataset.p===+n.dataset.party)));const el=document.querySelector('.graph-detail');if(i!==null){const x=questions[i],m=parties.filter((p,j)=>answers[i]*x.positions[j]>0).map(p=>p[0]);el.innerHTML=`<strong>${q(x,'topic')}</strong><p>${q(x,'statement')}</p><span>${m.length?t('aligned')+' '+m.join(', '):t('noAlign')}</span>`}}
function party(j){document.querySelectorAll('.edge').forEach(e=>{const on=+e.dataset.p===j;e.classList.toggle('lit',on);e.style.stroke=on?parties[j][2]:'';e.style.opacity=on?.9:.07});document.querySelectorAll('[data-party]').forEach(n=>n.classList.toggle('active',+n.dataset.party===j));document.querySelectorAll('[data-node]').forEach(n=>n.classList.toggle('active',[...document.querySelectorAll(`.edge[data-p="${j}"]`)].some(e=>+e.dataset.q===+n.dataset.node)));const topics=questions.filter((x,i)=>answers[i]&&x.positions[j]!==null&&answers[i]*x.positions[j]>0).map(x=>q(x,'topic'));document.querySelector('.graph-detail').innerHTML=`<strong>${parties[j][0]}</strong><p>${t('alignedTopics')}</p><span>${topics.join(', ')||t('noAlign')}</span>`}
render();if(document.modelContext?.registerTool)try{document.modelContext.registerTool({name:'answer_political_questions',description:'Set answers to one or more of the 21 questions.',inputSchema:{type:'object',properties:{answers:{type:'array',items:{type:'object',properties:{question:{type:'integer',minimum:1,maximum:questions.length},answer:{type:'integer',enum:[-1,0,1]}},required:['question','answer']}}},required:['answers']},execute(input){if(!input?.answers?.every(a=>Number.isInteger(a.question)&&a.question>=1&&a.question<=questions.length&&[-1,0,1].includes(a.answer)))throw new Error('Use question 1–21 and answer -1, 0 or 1.');input.answers.forEach(a=>answers[a.question-1]=a.answer);render();return{answered:count(),total:questions.length}}})}catch{}
